using System.Collections;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections.Generic;
[InitializeOnLoad] public static class StorybookTransitionValidation{
 const string Out="output/transition-view-ink/";static bool running;static double started;
 static StorybookTransitionValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("TRANSITION_UI_QA",false)){SessionState.SetBool("TRANSITION_UI_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);running=false;}};}
 static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","");UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Gameplay.unity");SessionState.SetBool("TRANSITION_UI_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("TRANSITION_UI_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;started=EditorApplication.timeSinceStartup;GameManager.single.StartCoroutine(Run());}if(running&&EditorApplication.timeSinceStartup-started>180){Check(false,"timeout");EditorApplication.isPlaying=false;}}
 static void Error(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error)Check(false,message);}
 static void Check(bool ok,string s)=>File.AppendAllText(Out+"validation.txt",(ok?"PASS ":"FAIL ")+s+"\n");
 static IEnumerator Run(){Application.logMessageReceived+=Error;var intro=Object.FindAnyObjectByType<CursedBookIntro>(FindObjectsInactive.Include);yield return new WaitForSecondsRealtime(2);if(intro&&!intro.Finished)intro.SkipStory();yield return new WaitForSecondsRealtime(2);yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();var ui=gc.homeUI.settingsUI;
 var transition=TransitionCanvas.single;Check(transition.group&&!transition.GetComponentInChildren<Animator>(),"New prefab has no legacy Animator");
 foreach(var size in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(size.x,size.y);yield return new WaitForSecondsRealtime(.2f);transition.ToBlack();yield return transition.WaitUntilCovered();Check(transition.IsCovered&&transition.page.texture&&transition.page.material.GetFloat("_PaperBlend")==0&&!transition.leafImage.enabled,"Outgoing frame covers destination without paper "+size);Check(transition.group.alpha==1&&transition.group.blocksRaycasts,"Fully covered and input blocked "+size);var veil=transition.page.rectTransform;var corners=new Vector3[4];veil.GetWorldCorners(corners);Check(corners[0].x<=0&&corners[0].y<=0&&corners[2].x>=Screen.width&&corners[2].y>=Screen.height,"Full viewport coverage "+size);yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"covered-"+size.x+"x"+size.y+".png",image.EncodeToPNG());Object.Destroy(image);yield return Router.single.GoToSkills();yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();image=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Out+"reveal-"+size.x+"x"+size.y+".png",image.EncodeToPNG());Object.Destroy(image);yield return new WaitForSecondsRealtime(.7f);Check(transition.group.alpha==0&&!transition.group.blocksRaycasts,"Reveal releases input "+size);yield return Router.single.GoToCampFromSkills();yield return new WaitForSecondsRealtime(.7f);}
 Time.timeScale=0;transition.ToBlack();yield return new WaitForSecondsRealtime(.1f);transition.ToClear();yield return new WaitForSecondsRealtime(.1f);transition.ToBlack();yield return new WaitForSecondsRealtime(.7f);Check(transition.group.alpha==1,"Interrupted fade and zero time scale");transition.ForceClear();yield return new WaitForSecondsRealtime(.7f);Check(transition.group.alpha==0&&!transition.group.blocksRaycasts,"Force clear releases input");Time.timeScale=1;yield return Router.single.GoToSkills();yield return new WaitForSecondsRealtime(.8f);Check(gc.skillsPanel.activeSelf&&!transition.group.blocksRaycasts,"Skills navigation");yield return Router.single.GoToCampFromSkills();yield return new WaitForSecondsRealtime(.8f);Check(gc.homeUI.gameObject.activeSelf&&!transition.group.blocksRaycasts,"Return home navigation");yield return Router.single.GoToMap();yield return new WaitForSecondsRealtime(.8f);Check(!transition.group.blocksRaycasts,"Map navigation releases input");yield return Router.single.GoToCashMall();yield return new WaitForSecondsRealtime(.8f);Check(!transition.group.blocksRaycasts,"Shop navigation releases input");yield return Router.single.GoToCampFromCashMall();yield return new WaitForSecondsRealtime(.8f);Check(gc.homeUI.gameObject.activeSelf&&!transition.group.blocksRaycasts,"Shop return home");StorybookEquipmentValidation.Resolution(1080,1920);File.AppendAllText(Out+"validation.txt","DONE\n");Application.logMessageReceived-=Error;EditorApplication.isPlaying=false;}
}
